mapper.select:
select t.create_user_id,t.create_user_id createUserId,t.address,t.store_type_cd,t.store_type_cd
storeTypeCd,t.name,t.tel,t.status_cd,t.status_cd statusCd,t.store_id,t.store_id storeId
from s_store t
where 1 =1

    and t.create_user_id= #{createUserId}


    and t.address= #{address}


    and t.store_type_cd= #{storeTypeCd}


    and t.name= #{name}


    and t.tel= #{tel}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}

order by t.create_time desc

    limit #{page}, #{row}

